import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define Threads    256
#define PVec       4
#define OcPerBlock 8

__global__ void conv2d_cute_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int K, int stride, int padding,
    int Hout, int Wout)
{
  extern __shared__ float sW_raw[];

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * H * Win),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * Cout * Hout * Wout),
      make_shape(Cout, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, K, K),
      make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));

  // Shared memory tensor for the weight tile of OcPerBlock output channels
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(OcPerBlock, Cin, K, K),
      make_stride((int64_t)Cin * K * K, (int64_t)K * K, (int64_t)K, (int64_t)1));

  const int weight_elems = OcPerBlock * Cin * K * K;
  for (int idx = tid; idx < weight_elems; idx += Threads) {
    int rem = idx;
    int kw = rem % K; rem /= K;
    int kh = rem % K; rem /= K;
    int cin = rem % Cin; rem /= Cin;
    int occ = rem;

    int oc = oc_base + occ;
    float val = 0.0f;
    if (oc < Cout) {
      val = mW(oc, cin, kh, kw);
    }
    sW(occ, cin, kh, kw) = val;
  }
  __syncthreads();

  // Precompute per-thread output pixel coordinates
  int   p_idx[PVec];
  int   oh_arr[PVec];
  int   ow_arr[PVec];
  int   ih0_arr[PVec];
  int   iw0_arr[PVec];
  bool  valid_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
      ih0_arr[i] = oh * stride - padding;
      iw0_arr[i] = ow * stride - padding;
      valid_arr[i] = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      ih0_arr[i] = 0;
      iw0_arr[i] = 0;
      valid_arr[i] = false;
    }
  }

  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (B != nullptr && oc < Cout) {
      bval = B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  for (int kh = 0; kh < K; ++kh) {
    for (int kw = 0; kw < K; ++kw) {
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (!valid_arr[i]) continue;
        int ih = ih0_arr[i] + kh;
        int iw = iw0_arr[i] + kw;
        if ((unsigned)ih >= (unsigned)H || (unsigned)iw >= (unsigned)Win) continue;

        for (int cin = 0; cin < Cin; ++cin) {
          float xval = mX(cin, ih, iw);
          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            float wval = sW(occ, cin, kh, kw);
            acc[occ][i] += xval * wval;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = acc[occ][i];
    }
  }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int stride, int padding) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  TORCH_CHECK(w.size(2) == w.size(3), "kernel must be square");
  int64_t K = w.size(2);

  TORCH_CHECK(stride > 0, "stride must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - K) / stride + 1;
  int64_t Wout = (Win + 2 * padding - K) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)OcPerBlock * Cin * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_cute_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)K, stride, padding,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.empty(out_channels))

        self.reset_parameters(in_channels, kernel_size)
        self._ext = conv2d_ext

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias,
            self.stride,
            self.padding,
        )

