import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ----------------------------------------------------------------------------
# Hand-authored PTX implementing a direct (naive) 2D convolution.
#
# Semantics match the CuTe/CUDA reference kernel:
#   Y[n, oc, oh, ow] = bias[oc] (optional) +
#       sum_{cin, kh, kw} X[n, cin, oh*stride - pad + kh, ow*stride - pad + kw]
#                         * W[oc, cin, kh, kw]
#
# One CUDA thread computes exactly one output element (n, oc, oh, ow).
# The global thread id is decomposed into (n, oc, oh, ow) via div/rem chains,
# mirroring the linearized index arithmetic used by the CuTe kernel.
# ----------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 X,
    .param .u64 W,
    .param .u64 B,
    .param .u64 Y,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 Hout,
    .param .u32 Wout
)
{
    .reg .pred  %p<12>;
    .reg .b32   %r<45>;
    .reg .b64   %rd<20>;
    .reg .f32   %f<6>;

    ld.param.u64 %rd1, [X];
    ld.param.u64 %rd2, [W];
    ld.param.u64 %rd3, [B];
    ld.param.u64 %rd4, [Y];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [Cin];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [Win];
    ld.param.u32 %r5,  [Cout];
    ld.param.u32 %r6,  [K];
    ld.param.u32 %r7,  [stride];
    ld.param.u32 %r8,  [padding];
    ld.param.u32 %r9,  [Hout];
    ld.param.u32 %r10, [Wout];

    cvta.to.global.u64 %rd5, %rd1;   // X global ptr
    cvta.to.global.u64 %rd6, %rd2;   // W global ptr
    cvta.to.global.u64 %rd7, %rd4;   // Y global ptr

    mov.u32 %r11, %ctaid.x;
    mov.u32 %r12, %ntid.x;
    mov.u32 %r13, %tid.x;
    mad.lo.s32 %r14, %r11, %r12, %r13;   // global thread id

    mul.lo.s32 %r15, %r9, %r10;          // Hout*Wout
    mul.lo.s32 %r16, %r15, %r5;          // Cout*Hout*Wout
    mul.lo.s32 %r17, %r16, %r1;          // N*Cout*Hout*Wout (total)

    setp.ge.s32 %p1, %r14, %r17;
    @%p1 bra DONE;

    // Decompose linear index -> (n, oc, oh, ow)
    div.s32 %r18, %r14, %r10;    // tmp1 = tid / Wout
    rem.s32 %r19, %r14, %r10;    // ow   = tid % Wout
    div.s32 %r20, %r18, %r9;     // tmp2 = tmp1 / Hout
    rem.s32 %r21, %r18, %r9;     // oh   = tmp1 % Hout
    div.s32 %r22, %r20, %r5;     // n    = tmp2 / Cout
    rem.s32 %r23, %r20, %r5;     // oc   = tmp2 % Cout

    mul.lo.s32 %r24, %r21, %r7;
    sub.s32    %r25, %r24, %r8;  // ih0 = oh*stride - padding
    mul.lo.s32 %r26, %r19, %r7;
    sub.s32    %r27, %r26, %r8;  // iw0 = ow*stride - padding

    mov.f32 %f1, 0f00000000;

    setp.eq.s64 %p2, %rd3, 0;
    @%p2 bra SKIP_BIAS;
    cvta.to.global.u64 %rd8, %rd3;
    mul.wide.s32 %rd9, %r23, 4;
    add.s64 %rd10, %rd8, %rd9;
    ld.global.f32 %f1, [%rd10];
SKIP_BIAS:

    mov.u32 %r28, 0;             // cin = 0
LOOP_CIN:
    setp.ge.s32 %p3, %r28, %r2;
    @%p3 bra END_CIN;

    mov.u32 %r29, 0;             // kh = 0
LOOP_KH:
    setp.ge.s32 %p4, %r29, %r6;
    @%p4 bra END_KH;

    add.s32 %r30, %r25, %r29;    // ih = ih0 + kh
    setp.lt.s32 %p5, %r30, 0;
    setp.ge.s32 %p6, %r30, %r3;
    or.pred %p7, %p5, %p6;
    @%p7 bra SKIP_KH_ROW;

    mov.u32 %r31, 0;             // kw = 0
LOOP_KW:
    setp.ge.s32 %p8, %r31, %r6;
    @%p8 bra END_KW;

    add.s32 %r32, %r27, %r31;    // iw = iw0 + kw
    setp.lt.s32 %p9, %r32, 0;
    setp.ge.s32 %p10, %r32, %r4;
    or.pred %p11, %p9, %p10;
    @%p11 bra SKIP_KW;

    // X index = ((n*Cin + cin)*H + ih)*Win + iw
    mad.lo.s32 %r33, %r22, %r2, %r28;
    mad.lo.s32 %r34, %r33, %r3, %r30;
    mad.lo.s32 %r35, %r34, %r4, %r32;
    mul.wide.s32 %rd11, %r35, 4;
    add.s64 %rd12, %rd5, %rd11;
    ld.global.f32 %f2, [%rd12];

    // W index = ((oc*Cin + cin)*K + kh)*K + kw
    mad.lo.s32 %r36, %r23, %r2, %r28;
    mad.lo.s32 %r37, %r36, %r6, %r29;
    mad.lo.s32 %r38, %r37, %r6, %r31;
    mul.wide.s32 %rd13, %r38, 4;
    add.s64 %rd14, %rd6, %rd13;
    ld.global.f32 %f3, [%rd14];

    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP_KW:
    add.s32 %r31, %r31, 1;
    bra.uni LOOP_KW;
END_KW:

SKIP_KH_ROW:
    add.s32 %r29, %r29, 1;
    bra.uni LOOP_KH;
END_KH:

    add.s32 %r28, %r28, 1;
    bra.uni LOOP_CIN;
END_CIN:

    // Y index = ((n*Cout + oc)*Hout + oh)*Wout + ow
    mad.lo.s32 %r39, %r22, %r5, %r23;
    mad.lo.s32 %r40, %r39, %r9, %r21;
    mad.lo.s32 %r41, %r40, %r10, %r19;
    mul.wide.s32 %rd15, %r41, 4;
    add.s64 %rd16, %rd7, %rd15;
    st.global.f32 [%rd16], %f1;

DONE:
    ret;
}
"""

_KERNEL_NAME = "conv2d_kernel"
_MODULE = None


def _get_module():
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Look up the compiled entry point to make sure the PTX module is valid."""
    module = _get_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"kernel '{_KERNEL_NAME}' not found in PTX module"
    return fn


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 96
        kernel_size = 11
        self.stride = 4
        self.padding = 2
        self.kernel_size = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(out_channels))
        self.reset_parameters(in_channels, kernel_size)

        self._module = _get_module()
        self._kernel = self._module.function(_KERNEL_NAME)

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in = in_channels * kernel_size * kernel_size
        bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
        init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "input must be float32"

        x = x.contiguous()
        w = self.weight.contiguous()
        b = self.bias.contiguous()

        N, Cin, H, Win = x.shape
        Cout, Cin_w, K, K2 = w.shape
        assert Cin_w == Cin and K == K2

        stride = self.stride
        padding = self.padding

        Hout = (H + 2 * padding - K) // stride + 1
        Wout = (Win + 2 * padding - K) // stride + 1
        assert Hout > 0 and Wout > 0

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        total = N * Cout * Hout * Wout
        threads = 256
        blocks = (total + threads - 1) // threads

        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        self._module.launch(
            self._kernel,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            args=[
                u64(x.data_ptr()),
                u64(w.data_ptr()),
                u64(b.data_ptr()),
                u64(y.data_ptr()),
                u32(N),
                u32(Cin),
                u32(H),
                u32(Win),
                u32(Cout),
                u32(K),
                u32(stride),
                u32(padding),
                u32(Hout),
                u32(Wout),
            ],
            stream=stream,
        )

        return y
